func runMemoryLoopAdd(ctx context.Context, w io.Writer, opts memoryLoopAddOptions) error {
	state, err := loadMemoryLoopState(ctx)
	if err != nil {
		return fmt.Errorf("load memory-loop state: %w", err)
	}
	if err := ensureMemoryLoopStore(ctx, state); err != nil {
		return err
	}

	kind, err := parseMemoryLoopKind(opts.Kind)
	if err != nil {
		return err
	}
	scopeKind, scopeValue, ownerEmail, err := resolveAddScope(ctx, opts.Scope)
	if err != nil {
		return err
	}

	records, added, err := memoryloop.AddManualRecord(state.Store.Records, memoryloop.ManualRecordInput{
		Kind:       kind,
		Title:      opts.Title,
		Body:       opts.Body,
		ScopeKind:  scopeKind,
		ScopeValue: scopeValue,
		OwnerEmail: ownerEmail,
	}, time.Now().UTC())
	if err != nil {
		return fmt.Errorf("add manual memory: %w", err)
	}

	state.Store.Records = records
	if err := memoryloop.SaveState(ctx, state); err != nil {
		return fmt.Errorf("save memory-loop state: %w", err)
	}

	fmt.Fprintf(w, "Added memory: %s\n", added.ID)
	return nil
}

	case memoryloop.LifecycleActionArchive:
		return "Archived"
	default:
		return "Updated"
	}
}

func displayToggle(enabled bool) string {
	if enabled {
		return "on"
	}
	return "off"
}

func parseMemoryLoopKind(raw string) (memoryloop.Kind, error) {
	kind := memoryloop.Kind(strings.ToLower(strings.TrimSpace(raw)))
	switch kind {
	case memoryloop.KindRepoRule,
		memoryloop.KindWorkflowRule,
		memoryloop.KindAgentInstruction,
		memoryloop.KindSkillPatch,
		memoryloop.KindAntiPattern:
		return kind, nil
	default:
		return "", fmt.Errorf("invalid memory kind: %s", raw)
	}
}

func resolveAddScope(ctx context.Context, rawScope string) (memoryloop.ScopeKind, string, string, error) {
	switch memoryLoopScopeMode(strings.ToLower(strings.TrimSpace(rawScope))) {
	case "", memoryLoopScopeMe:
		ownerID, err := configuredMemoryLoopOwnerID(ctx)
		if err != nil {
			return "", "", "", err
		}
		author, err := GetGitAuthor(ctx)
		if err != nil {
			return "", "", "", fmt.Errorf("resolve git author: %w", err)
		}
		return memoryloop.ScopeKindMe, ownerID, author.Email, nil
	case memoryLoopScopeRepo:
		return memoryloop.ScopeKindRepo, "", "", nil
	case memoryLoopScopeBranch:
		repo, err := openRepository(ctx)
		if err != nil {
			return "", "", "", fmt.Errorf("open git repository: %w", err)
		}
		branch := strategy.GetCurrentBranchName(repo)
		if branch == "" {
			return "", "", "", errors.New("current HEAD is detached; cannot use branch scope")
		}
		author, err := GetGitAuthor(ctx)
		if err != nil {
			return "", "", "", fmt.Errorf("resolve git author: %w", err)
		}
		return memoryloop.ScopeKindBranch, branch, author.Email, nil

		// Blur current, advance focus, focus next
		m.addFields[m.addFocus].Blur()
		m.addFocus = (m.addFocus + 1) % len(m.addFields)
		m.addFields[m.addFocus].Focus()
		return m, textinput.Blink

	case msg.String() == "shift+tab":
		m.addFields[m.addFocus].Blur()
		m.addFocus = (m.addFocus + len(m.addFields) - 1) % len(m.addFields)
		m.addFields[m.addFocus].Focus()
		return m, textinput.Blink

	case msg.String() == "enter":
		if m.addFocus < len(m.addFields)-1 {
			// Not on last field -- advance to next
			m.addFields[m.addFocus].Blur()
			m.addFocus++
			m.addFields[m.addFocus].Focus()
			return m, textinput.Blink
		}
		// On last field -- submit
		input := memoryloop.ManualRecordInput{
			Kind:       memoryloop.Kind(m.addFields[0].Value()),
			Title:      m.addFields[1].Value(),
			Body:       m.addFields[2].Value(),
			ScopeKind:  memoryloop.ScopeKind(m.addFields[3].Value()),
			ScopeValue: "",
		}
		m.addMode = false
		return m, func() tea.Msg { return addMemoryMsg{input: input} }
	}

	// Delegate to the focused text input for character input
	var cmd tea.Cmd
	m.addFields[m.addFocus], cmd = m.addFields[m.addFocus].Update(msg)
	return m, cmd
}

func (m memoriesModel) view() string {
